// "Path from the root": picking an artery, vein or nerve lights up everything it leaves, drains into or comes off, up to the aorta, a vena cava or a nerve root, and the same
// path on the other side of the body. The parents come from app/mj-vessel-parents.json (generated by scripts/build-vessel-parents.mjs).
import parentsFile from './mj-vessel-parents.json';

export type ParentMap = Readonly<Record<string, readonly string[]>>;
export const VESSEL_PARENTS: ParentMap = (parentsFile as {parents: Record<string, string[]>}).parents;

/** Mesh names carry a 3-digit duplicate suffix in the nerve stream ("Median nerve.l.001"): the parents are keyed without it. */
export const plainName = (name: string): string => name.replace(/\.\d{3}$/, '');

/** The same structure on the other side of the body (Right/Left words, right/left inside a name, the nerve suffix .r/.l); the name itself when it has no side. */
export function mirrorName(name: string): string {
  const n = plainName(name);
  if (/\.[rl]$/.test(n)) return n.replace(/\.([rl])$/, (_, s: string) => (s === 'r' ? '.l' : '.r'));
  return n.replace(/\b(Right|Left|right|left)\b/g, m => ({Right: 'Left', Left: 'Right', right: 'left', left: 'right'}[m] as string));
}

/** Every structure above `name` (parents, their parents … up to the root), nearest first, without `name` itself. */
export function pathAbove(name: string, parents: ParentMap = VESSEL_PARENTS): string[] {
  const out: string[] = [], seen = new Set<string>([plainName(name)]);
  let level = [plainName(name)];
  while (level.length) {
    const next: string[] = [];
    for (const n of level) for (const p of parents[n] ?? []) if (!seen.has(p)) { seen.add(p); out.push(p); next.push(p); }
    level = next;
  }
  return out;
}

/**
 * The names to light up for a selection, without the selected names themselves: the path above each of them, and — for both sides at once — the other side's structure with its
 * own path. A name with no side (the aorta, a vena cava) is its own mirror, so it appears once.
 */
export function pathHighlightNames(selected: readonly string[], parents: ParentMap = VESSEL_PARENTS): Set<string> {
  const own = new Set(selected.map(plainName)), out = new Set<string>();
  for (const name of own) {
    const known = parents[name] !== undefined || Object.values(parents).some(l => l.includes(name));
    if (!known) continue;   // not an artery, vein or nerve of the parent table: nothing to light up
    for (const p of pathAbove(name, parents)) out.add(p);
    const other = mirrorName(name);
    if (other !== name) { out.add(other); for (const p of pathAbove(other, parents)) out.add(p); }
  }
  for (const n of own) out.delete(n);
  return out;
}
